/**
 * חשיפה מדורגת (REDESIGN-PLAN §6.2): [data-rv="1|2|3"] = ראשי / משני / שלישוני.
 * בתוך [data-rv-group] כל פריט מקבל --rv-i לפי סדר המסמך (stagger 60ms, תקרה 6).
 * חושף פעם אחת. בלי JS / בהפחתת תנועה — הכול נראה (ה-CSS מותנה ב-html.js ובהעדפה).
 */
export function initReveal(root: ParentNode = document) {
  root.querySelectorAll<HTMLElement>('[data-rv-group]').forEach((g) => {
    g.querySelectorAll<HTMLElement>('[data-rv]').forEach((el, i) => el.style.setProperty('--rv-i', String(i)));
  });
  const els = Array.from(root.querySelectorAll<HTMLElement>('[data-rv]'));
  if (!('IntersectionObserver' in window)) { els.forEach((el) => el.classList.add('rv-in')); return; }
  const io = new IntersectionObserver((entries) => {
    for (const e of entries) {
      if (!e.isIntersecting) continue;
      e.target.classList.add('rv-in');
      io.unobserve(e.target);
    }
  }, { threshold: 0.15, rootMargin: '0px 0px -8% 0px' });
  els.forEach((el) => io.observe(el));
  // רשת ביטחון: קפיצה לעוגן / טעינה באמצע הדף
  addEventListener('load', () => setTimeout(() => {
    els.forEach((el) => { const r = el.getBoundingClientRect(); if (r.top < innerHeight && r.bottom > 0) el.classList.add('rv-in'); });
  }, 300));
}
