/**
 * חשיפת כותרות מילה-מילה (REDESIGN-PLAN §6): [data-split] → כל מילה בתוך מסכה, עולה מ-110% ומתיישרת.
 * עברית: מפצלים למילים בלבד (לעולם לא לאותיות — ניקוד/ליגטורות/כיווניות נשמרים). אלמנטים פנימיים
 * (<br>, <b>, <span lang="en">) נשמרים כיחידה אחת. קוראי מסך: הטקסט נשאר רציף (span בלבד, בלי aria-hidden).
 */
import { gsap, ScrollTrigger, reduced } from './core';

function wrap(el: HTMLElement) {
  if (el.dataset.splitDone) return;
  el.dataset.splitDone = '1';
  const nodes = Array.from(el.childNodes);
  el.textContent = '';
  const mk = (inner: Node) => {
    const w = document.createElement('span'); w.className = 'sw';
    const i = document.createElement('span'); i.className = 'swi';
    i.appendChild(inner); w.appendChild(i); return w;
  };
  for (const n of nodes) {
    if (n.nodeType === Node.TEXT_NODE) {
      const parts = (n.textContent ?? '').split(/(\s+)/);
      for (const p of parts) {
        if (!p) continue;
        if (/^\s+$/.test(p)) el.appendChild(document.createTextNode(' '));
        else el.appendChild(mk(document.createTextNode(p)));
      }
    } else if ((n as HTMLElement).tagName === 'BR') el.appendChild(n);
    else el.appendChild(mk(n));
  }
}

export function initSplit(root: ParentNode = document) {
  const els = Array.from(root.querySelectorAll<HTMLElement>('[data-split]'));
  if (reduced()) return;
  els.forEach((el) => {
    wrap(el);
    const words = el.querySelectorAll('.swi');
    gsap.set(words, { yPercent: 115, rotate: 3, opacity: 0 });
    const play = () => gsap.to(words, { yPercent: 0, rotate: 0, opacity: 1, duration: 1.1, ease: 'expo.out', stagger: 0.06, delay: Number(el.dataset.splitDelay ?? 0) });
    if (el.dataset.split === 'now') { (el as any)._play = play; return; } // מופעל ידנית (אחרי האינטרו)
    ScrollTrigger.create({ trigger: el, start: 'top 88%', once: true, onEnter: play });
  });
}

/** להפעלה ידנית של [data-split="now"] */
export function playSplit(el: Element | null) { (el as any)?._play?.(); }
