/**
 * במאי הסצנה (REDESIGN-PLAN §4.2) — הדף מכתיב לבמה, לא להפך.
 * כל סקשן בדף הבית מצהיר data-beat-t="<T>" (מיקום על ציר הבמה, 0..5) ואופציונלית data-veil="<0..1>".
 * בזמן שסקשן נקרא הבמה *שוהה* על ה-T שלו (המצלמה לא זזה מתחת לטקסט); המעבר ל-T של הסקשן הבא
 * קורה ברצועת גלילה קצרה כשהסקשן הבא נכנס (60%→20% מגובה המסך). המלכה עושה את הצעד בתוך המעבר
 * (MOVE_WINDOW של timeline.ts) ורק אחריו המצלמה נוסעת.
 * מחזיר את חוזה ה-Timeline שהבמה כבר מכירה ({ T, refresh, track }) — בלי לגעת ב-stage.ts.
 */
import type { Timeline } from '../stage/timeline';

interface Beat { el: HTMLElement; T: number; veil: number; side: number; top: number; bottom: number; }
interface Knot { y: number; T: number; veil: number; side: number; }

const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const ease = (t: number) => t * t * (3 - 2 * t);

export function makeDirector(sections: HTMLElement[], veilEl?: HTMLElement | null): Timeline & { veil(): number; drift(): number } {
  let knots: Knot[] = [];
  let runs: { y0: number; y1: number; hold: boolean }[] = [];
  const refresh = () => {
    const vh = innerHeight;
    const beats: Beat[] = sections.map((el) => {
      const r = el.getBoundingClientRect();
      return { el, T: Number(el.dataset.beatT ?? 0), veil: Number(el.dataset.veil ?? 0.3), side: Number(el.dataset.side ?? 0), top: r.top + scrollY, bottom: r.bottom + scrollY };
    });
    const ks: Knot[] = [];
    beats.forEach((b, i) => {
      if (i === 0) { ks.push({ y: 0, T: b.T, veil: b.veil, side: b.side }); return; }
      // המעבר: ברירת מחדל — מרגע שראש הסקשן ב-60% מהמסך ועד שהוא ב-20%; הפוגות מגדירות data-enter="a,b"
      // (למשל "0.35,-0.25": המהלך קורה כשההפוגה כבר ממלאת את המסך)
      const A = beats[i - 1];
      const mix = (fT: number, fV: number): Omit<Knot, 'y'> => ({ T: lerp(A.T, b.T, fT), veil: lerp(A.veil, b.veil, fV), side: lerp(A.side, b.side, fV) });
      if (b.el.dataset.curve) {
        // עקומה מפורשת "pos:fT:fV,…": pos = ראש הסקשן ביחידות גובה-מסך; fT = חלק מהמעבר ב-T; fV = חלק מהמעבר בווילון.
        // (הפוגות: הגלישה מאחורי סוף הסקשן הקודם, "הדק" של המהלך כשההפוגה שליש-גלויה, וקפיצת T שקטה אחר כך)
        for (const part of b.el.dataset.curve.split(',')) {
          const [pos, fT, fV] = part.split(':').map(Number);
          ks.push({ y: b.top - vh * pos, ...mix(fT, fV) });
        }
      } else {
        const [ea, eb] = (b.el.dataset.enter ?? '0.6,0.2').split(',').map(Number);
        ks.push({ y: b.top - vh * ea, ...mix(0, 0) });
        ks.push({ y: b.top - vh * eb, ...mix(1, 1) });
      }
    });
    for (let i = 1; i < ks.length; i++) if (ks[i].y <= ks[i - 1].y) ks[i].y = ks[i - 1].y + 1;
    // סוף הדף — כדי שגם ה-hold האחרון יסחוף
    ks.push({ y: Math.max(ks[ks.length - 1].y + 1, document.documentElement.scrollHeight - vh), T: ks[ks.length - 1].T, veil: ks[ks.length - 1].veil, side: ks[ks.length - 1].side });
    knots = ks;
    // ריצות של T קבוע (קריאה) → סחיפת מצלמה 0→1; מעברי T → חזרה 1→0 (רציף, בלי קפיצה)
    runs = [];
    let i0 = 0;
    for (let i = 1; i < ks.length; i++) {
      const same = Math.abs(ks[i].T - ks[i - 1].T) < 1e-6;
      const nextSame = i + 1 < ks.length && Math.abs(ks[i + 1].T - ks[i].T) < 1e-6;
      if (same && !nextSame) { runs.push({ y0: ks[i0].y, y1: ks[i].y, hold: true }); i0 = i; }
      else if (!same && (i + 1 >= ks.length || nextSame)) { runs.push({ y0: ks[i0].y, y1: ks[i].y, hold: false }); i0 = i; }
    }
  };
  const sample = (y: number): { T: number; veil: number; side: number } => {
    const n = knots.length;
    if (!n) return { T: 0, veil: 0.3, side: 0 };
    if (y <= knots[0].y) return knots[0];
    for (let i = 1; i < n; i++) {
      const a = knots[i - 1], b = knots[i];
      if (y < b.y) {
        const f = (y - a.y) / (b.y - a.y);
        // הווילון מגיע ליעד כבר ב-35% מהמעבר: בהפוגה הסצנה מוארת לפני שהמצלמה והמלכה זזות
        const fv = f;
        // T ליניארי בגלילה (דוד: "מהירות הגלילה מול תנועת הרינדור — הכול צריך להיות הגיוני"): אותה תנועת
        // גלגלת = אותה תנועת מצלמה. ההחלקה היחידה באה מ-Lenis; כאן אין easing נוסף שמכווץ את הנסיעה לקפיצה.
        return { T: lerp(a.T, b.T, f), veil: lerp(a.veil, b.veil, fv), side: lerp(a.side, b.side, fv) };
      }
    }
    return knots[n - 1];
  };
  let lastVeil = -1, lastSide = -1;
  const applyVeil = (v: number, sd = 0) => {
    if (!veilEl) return;
    if (Math.abs(v - lastVeil) >= 0.004) { lastVeil = v; veilEl.style.setProperty('--page-veil', v.toFixed(3)); }
    if (Math.abs(sd - lastSide) >= 0.004) { lastSide = sd; veilEl.style.setProperty('--side', sd.toFixed(3)); }
  };
  let raf = 0;
  const onScroll = () => { if (!raf) raf = requestAnimationFrame(() => { raf = 0; applyVeil(sample(scrollY).veil, sample(scrollY).side); }); };
  addEventListener('scroll', onScroll, { passive: true });
  refresh();
  applyVeil(sample(scrollY).veil, sample(scrollY).side);
  return {
    T: () => sample(scrollY).T,
    refresh: () => { refresh(); applyVeil(sample(scrollY).veil, sample(scrollY).side); },
    track: () => 0,
    drift: () => {
      const y = scrollY;
      for (const r of runs) if (y >= r.y0 && y <= r.y1) { const f = (y - r.y0) / Math.max(1, r.y1 - r.y0); return r.hold ? f : 1 - f; }
      return 0;
    },
    veil: () => sample(scrollY).veil,
  };
}
